/* Preset and option catalogue of the start menu.  The data (som_launcher_catalog.c) is generated by gen_catalog.py from
 * tools/companion/randomizer/presets.json; option keys are the generator's own setting names (Moppu/SecretOfManaRandomizer v1.49,
 * LGPL-2.1).  Pure C99. */
#ifndef SOM_LAUNCHER_CATALOG_H
#define SOM_LAUNCHER_CATALOG_H

#include <stddef.h>
#include <stdint.h>

#define SL_MAX_OPTS 128          /* mode options + common options of one mode */
#define SL_MAX_MODES 8
#define SL_MAX_PRESETS 32

enum sl_otype { SL_O_BOOL = 0, SL_O_ENUM, SL_O_NUM, SL_O_MULTI };

struct sl_value { const char *v, *label, *full; };   /* full: the generator's own display text when `label` is a shortened form, else "" */

struct sl_req { const char *key, *vals; };      /* option visible only while option `key` holds one of "|a|b|" */

struct sl_option {
  const char *key, *label, *group, *help;
  uint8_t type, advanced, randomize, decimals;
  uint16_t nvalues;                              /* BOOL: 2 (no, yes); ENUM / MULTI: the declared values */
  const struct sl_value *values;
  int32_t def;                                   /* BOOL/ENUM: value index; NUM: fixed point (value * 10^decimals); MULTI: bit mask */
  int32_t min, max, step;                        /* NUM, fixed point */
  uint16_t npool; const char *const *pool;       /* "randomize all" draws from these value strings when npool > 0 */
  uint8_t nreq; const struct sl_req *req;
};

enum sl_cons_kind { SL_C_ANY = 0 /* at least one of the bool options is yes */, SL_C_LE /* a <= b (enum values compared as numbers) */ };
struct sl_cons { uint8_t kind, n; const char *key[3]; };

struct sl_set { const char *key, *val; };

struct sl_mode {
  const char *key, *name, *desc;
  uint16_t nopts; const struct sl_option *opts;
  uint8_t ndiff; const char *const *diff; uint8_t def_diff;      /* ndiff 0: the mode has no difficulty argument */
  uint8_t ncons; const struct sl_cons *cons;
};

struct sl_preset {
  const char *id, *name, *desc;
  uint8_t mode;                                   /* index in sl_modes */
  int8_t diff;                                    /* difficulty index or -1 (mode default) */
  uint16_t nset; const struct sl_set *set;
};

extern const char sl_generator_version[];          /* "1.49" */
extern const char sl_generator_commit[];           /* "1404b7b" */
extern const int sl_nmodes;
extern const struct sl_mode sl_modes[];
extern const int sl_ncommon;
extern const struct sl_option sl_common[];
extern const int sl_npresets;
extern const struct sl_preset sl_presets[];

#endif
